const { applyDiscount } = require('./discount');
const { applyTax } = require('./tax');

const round2 = (n) => Math.round(n * 100) / 100;

// Discounts apply to the pre-tax subtotal; tax applies to what is left. A discount
// can bring the subtotal down to zero but never below.
function total(items, { discount, taxRate = 0 } = {}) {
  const subtotal = items.reduce((sum, it) => sum + it.price * it.qty, 0);
  const taxed = applyTax(subtotal, taxRate);
  return round2(applyDiscount(taxed, discount));
}

module.exports = { total };
// discount: { type: 'percent', value: 0..100 } | { type: 'fixed', value: amount } | undefined
function applyDiscount(amount, discount) {
  if (!discount) return amount;
  if (discount.type === 'percent') return amount * (1 - discount.value / 100);
  if (discount.type === 'fixed') return amount - discount.value;
  throw new Error(`Unknown discount type: ${discount.type}`);
}

module.exports = { applyDiscount };
function applyTax(amount, rate) {
  return amount * (1 + rate);
}

module.exports = { applyTax };
